	hasRuntimeApiKey(providerId: string): boolean {
		return this.credentials.hasRuntimeApiKey(providerId);
	}

	async setRuntimeApiKey(
		providerId: string,
		apiKey: string,
		options?: { allowNetwork?: boolean },
	): Promise<void> {
		this.credentials.setRuntimeApiKey(providerId, apiKey);
		const auth = new Map(this.snapshot.auth).set(providerId, { type: "api_key", source: "runtime API key" });
		const configuredProviders = new Set(this.snapshot.configuredProviders).add(providerId);
		const storedProviders = new Set(this.snapshot.storedProviders).add(providerId);
		this.snapshot = {
			...this.snapshot,
			auth,
			configuredProviders,
			storedProviders,
			available: this.snapshot.all.filter(
				(model) => configuredProviders.has(model.provider) && this.isCatalogModelAvailable(model),
			),
		};
		await this.refresh({ allowNetwork: options?.allowNetwork ?? this.allowModelNetwork });
	}

	async removeRuntimeApiKey(providerId: string): Promise<void> {
		this.credentials.removeRuntimeApiKey(providerId);
		await this.refresh({ allowNetwork: this.allowModelNetwork });
	}

